// Проверяем тип входящего сообщения
// Поддерживаем: документ (CSV/Excel), текст с данными или команду /analyze
const msg = $input.first().json.message ?? {};

const hasDocument = !!msg.document;
const hasText = !!msg.text;
const chatId = msg.chat?.id ?? msg.from?.id;

if (!hasDocument && !hasText) {
  return [{ json: { skip: true, chatId, reason: 'no_content' } }];
}

return [{
  json: {
    skip: false,
    chatId,
    hasDocument,
    hasText,
    text: msg.text ?? '',
    fileId: msg.document?.file_id ?? null,
    fileName: msg.document?.file_name ?? null,
    mimeType: msg.document?.mime_type ?? null
  }
}];

// Парсинг текстовых данных из Telegram (если менеджер вставил текст/JSON вручную)
const raw = $input.first().json.text ?? '';

let rows = [];

// Пробуем JSON
try {
  const parsed = JSON.parse(raw);
  rows = Array.isArray(parsed) ? parsed : [parsed];
} catch(e) {
  // Пробуем CSV (разделители: запятая или точка с запятой)
  const lines = raw.trim().split('\n').filter(Boolean);
  if (lines.length >= 2) {
    const sep = lines[0].includes(';') ? ';' : ',';
    const headers = lines[0].split(sep).map(h => h.trim().replace(/^"|"$/g, ''));
    rows = lines.slice(1).map(line => {
      const vals = line.split(sep).map(v => v.trim().replace(/^"|"$/g, ''));
      const obj = {};
      headers.forEach((h, i) => { obj[h] = isNaN(vals[i]) ? vals[i] : Number(vals[i]); });
      return obj;
    });
  }
}

if (rows.length === 0) {
  return [{ json: { error: 'Не удалось распарсить данные', raw } }];
}

return rows.map(r => ({ json: r }));

// Собираем все рассчитанные товары в один массив и передаём в AI одним запросом
const items = $input.all();
const products = items.map(i => i.json);

return [{ json: { products } }];

// Расчёт показателей по каждому товару
const items = $input.all();

return items.map(item => {
  const d = item.json;

  // Динамика продаж
  const salesNow   = d.revenue_current  ?? d.revenue  ?? 0;
  const salesPrev  = d.revenue_previous ?? salesNow;
  const salesDelta = salesPrev > 0 ? ((salesNow - salesPrev) / salesPrev) * 100 : 0;

  const ordersNow   = d.ordered_units_current  ?? d.ordered_units  ?? 0;
  const ordersPrev  = d.ordered_units_previous ?? ordersNow;
  const ordersDelta = ordersPrev > 0 ? ((ordersNow - ordersPrev) / ordersPrev) * 100 : 0;

  // Конверсия
  const views    = d.hits_view    ?? 1;
  const sessions = d.session_view ?? 1;
  const toCart   = d.hits_tocart  ?? 0;
  const convToCart = sessions > 0 ? (toCart / sessions) * 100 : 0;

  // Возвраты и отмены
  const returns   = d.returns         ?? 0;
  const cancelled = d.cancelled_units ?? 0;
  const returnRate = ordersNow > 0 ? (returns / ordersNow) * 100 : 0;
  const cancelRate = ordersNow > 0 ? (cancelled / ordersNow) * 100 : 0;

  // Остатки — дни до out-of-stock
  const stock      = d.stock_qty  ?? 0;
  const dailySales = salesNow / 14;
  const daysLeft   = dailySales > 0 ? Math.round(stock / dailySales) : 999;

  // Экономика
  const cogs       = d.cost_price  ?? 0;
  const price      = d.price       ?? 0;
  const commission = d.commission  ?? 0;
  const logistics  = d.logistics   ?? 0;
  const adSpend    = d.ad_spend    ?? 0;
  const margin     = price > 0 ? ((price - cogs - commission - logistics - adSpend) / price) * 100 : 0;
  const drr        = salesNow > 0 ? (adSpend / salesNow) * 100 : 0;

  // Рейтинг и отзывы
  const rating   = d.rating        ?? 0;
  const reviews  = d.reviews_count ?? 0;

  // Приоритет (pre-score для подсказки AI)
  let priority = 'low';
  if (salesDelta <= -20 || ordersDelta <= -20 || daysLeft < 7) priority = 'high';
  else if (daysLeft < 14 || daysLeft < 14)                     priority = 'high';
  else if (salesDelta >= 15 || ordersDelta >= 15)              priority = 'medium';
  else if (drr > 25 || returnRate > 15 || cancelRate > 20)    priority = 'medium';
  else if (convToCart < 3)                                     priority = 'medium';

  return {
    json: {
      sku:         d.sku ?? d.article ?? d.Артикул ?? 'N/A',
      name:        d.name ?? d.product_name ?? d.Название ?? 'Без названия',
      salesNow:    Math.round(salesNow),
      salesDelta:  Math.round(salesDelta),
      ordersNow,
      ordersDelta: Math.round(ordersDelta),
      convToCart:  Math.round(convToCart * 10) / 10,
      returnRate:  Math.round(returnRate * 10) / 10,
      cancelRate:  Math.round(cancelRate * 10) / 10,
      daysLeft,
      stock,
      margin:      Math.round(margin),
      drr:         Math.round(drr),
      adSpend,
      price,
      rating,
      reviews,
      priority
    }
  };
});

