const raw = $input.first().json;
const text = raw.content?.[0]?.text ?? '{"tasks":[]}';

let parsed;
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = { tasks: [], error: 'parse failed', raw: text };
}

const tasks = parsed.tasks ?? [];

// Сортировка: high → medium → low
const order = { high: 0, medium: 1, low: 2 };
tasks.sort((a, b) => (order[a.priority] ?? 2) - (order[b.priority] ?? 2));

// Форматируем текст для Telegram
const priorityEmoji = { high: '🔴', medium: '🟡', low: '🟢' };
const categoryLabel = {
  restock:   '📦 Допоставка',
  price:     '💰 Цена / скидка',
  card:      '🖼 Карточка',
  ads_up:    '📈 Усилить рекламу',
  ads_down:  '📉 Снизить рекламу',
  returns:   '↩️ Возвраты',
  scale:     '🚀 Масштабирование',
  freeze:    '❄️ Заморозить закуп'
};

const lines = tasks.map(t =>
  `${priorityEmoji[t.priority] ?? '⚪'} *${t.name}* \`[${t.sku}]\`\n` +
  `${categoryLabel[t.category] ?? t.category}\n` +
  `✅ ${t.action}\n` +
  `💬 ${t.reason}\n` +
  `⏰ ${t.deadline}`
).join('\n\n─────────────\n\n');

const date = new Date().toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric' });
const highCount = tasks.filter(t => t.priority === 'high').length;
const header = `📊 *Задачи по Ozon — ${date}*\n🔴 Срочных: ${highCount} | Всего: ${tasks.length}\n`;

const telegramText = tasks.length > 0
  ? header + '\n' + lines
  : `📊 *Задачи по Ozon — ${date}*\n\n✅ Нет срочных задач — все показатели в норме`;

return [{
  json: {
    tasks,
    telegramText,
    totalTasks: tasks.length,
    highCount
  }
}];

